          "answerText": "Зсув \\(x\\) на \\(T/k\\) змінює аргумент \\(kx+b\\) на \\(T\\). Сталий \\(b\\) не впливає на період; якщо потрібен додатний період, беруть модуль \\(T/k\\).",
          "optionSource": "prepared-test-2018",
          "explanationSource": "prepared-test-2018"
